"""Unit tests for immutable presentation ViewModels."""import pytestfrom src.core.session import GameSessionfrom src.core.view_models import (    CombatViewModel,    ShopViewModel,    LootViewModel,    MapViewModel,    AbilityDraftViewModel,)from src.core.persistence import MemoryStorageBackendfrom src.core.save_manager import SaveManagerfrom src.entities.enemy import Enemy, EnemyTierfrom src.entities.actor import Statsfrom src.entities.item import Item, ItemTypefrom src.systems.combat import CombatSystemdef create_session() -> GameSession:    mem_storage = MemoryStorageBackend()    save_mgr = SaveManager(storage=mem_storage)    session = GameSession(save_mgr=save_mgr)    session.start_new_game(class_id="warrior")    return sessiondef test_combat_view_model_snapshot():    """CombatViewModel provides an immutable, complete snapshot of a live encounter."""    session = create_session()    enemy = Enemy(        name="Cave Troll",        tier=EnemyTier.COMMON,        stats=Stats(max_hp=80, attack=15, defense=5, speed=8),        floor_level=1,        exp_reward=30,        gold_reward=15,    )    session.state.combat = CombatSystem(player=session.player, enemy=enemy, bus=session.bus)    vm = session.get_combat_view_model()    assert vm is not None    assert isinstance(vm, CombatViewModel)    assert vm.hero.name == "Sir Aethelgard"    assert vm.hero.current_hp == session.player.current_hp    assert vm.hero.hp_percent == 1.0    assert vm.enemy.name == "Cave Troll"    assert vm.enemy.current_hp == 80    assert vm.is_active is True    assert vm.is_qte_active is Falsedef test_shop_view_model_snapshot():    """ShopViewModel exposes formatted prices, afford status, and pouch slots."""    session = create_session()    session.player.gold = 50    item1 = Item(        id="potion",        name="Healing Potion",        description="Heals HP",        item_type=ItemType.CONSUMABLE,        gold_value=20,    )    item2 = Item(        id="relic",        name="Ancient Relic",        description="Priceless",        item_type=ItemType.MATERIAL,        gold_value=100,    )    session.state.merchant_stock = [(item1, 20), (item2, 100)]    vm = session.get_shop_view_model()    assert isinstance(vm, ShopViewModel)    assert vm.player_gold == 50    assert len(vm.stock) == 2    assert vm.stock[0].name == "Healing Potion"    assert vm.stock[0].can_afford is True    assert vm.stock[1].name == "Ancient Relic"    assert vm.stock[1].can_afford is False    assert vm.can_buy_any is Truedef test_loot_view_model_snapshot():    """LootViewModel reports pending loot items and pouch occupancy."""    session = create_session()    item = Item(        id="iron_helm",        name="Iron Helm",        description="Armor",        item_type=ItemType.EQUIPMENT,        gold_value=35,    )    session.state.pending_loot = [item]    vm = session.get_loot_view_model()    assert isinstance(vm, LootViewModel)    assert vm.has_loot is True    assert vm.pouch_has_space is True    assert len(vm.items) == 1    assert vm.items[0].name == "Iron Helm"def test_map_view_model_snapshot():    """MapViewModel captures act, floor, biome, and accessible paths."""    session = create_session()    vm = session.get_map_view_model()    assert vm is not None    assert isinstance(vm, MapViewModel)    assert vm.act == 1    assert vm.floor == 1    assert vm.total_floors > 0    assert len(vm.available_nodes) > 0def test_ability_draft_view_model_snapshot():    """AbilityDraftViewModel reflects pending choices and candidate options."""    session = create_session()    session.player.pending_ability_choices = ["STANDARD"]    vm = session.get_ability_draft_view_model()    assert isinstance(vm, AbilityDraftViewModel)    assert vm.has_pending_draft is True    assert vm.pending_choices_count == 1    assert len(vm.choices) > 0